#!/usr/bin/env bash\nset -euo pipefail\n\n# Create temporary directory\nTMPDIR=$(mktemp -d)\ncleanup() {\n  rm -rf "$TMPDIR"\n}\ntrap cleanup EXIT\n\n# Populate with files\n# Two .txt files to make .txt the most common extension\ntouch "$TMPDIR/file1.txt"\ntouch "$TMPDIR/file2.txt"\n# One .log file\necho "log entry" > "$TMPDIR/file3.log"\n# One binary file of ~10KB\ndd if=/dev/zero of="$TMPDIR/big.bin" bs=1K count=10 status=none\n\n# Run the summary script\noutput=$(bash ../src/summary.sh "$TMPDIR")\n\n# Verify file count (should be 4)\nif [[ "$output" != *"Scanned 4 files"* ]]; then\n  echo "File count mismatch: $output"\n  exit 1\nfi\n\n# Verify most common extension is .txt\nif [[ "$output" != *"most common type: .txt"* ]]; then\n  echo "Extension detection mismatch: $output"\n  exit 1\nfi\n\n# Verify size information is present\nif [[ "$output" != *"total size"* ]]; then\n  echo "Missing size info: $output"\n  exit 1\nfi\n\n# If we reach here, all checks passed\necho "All tests passed"
